  function findService(serviceId){return getItems(selected()).find(service=>service.id===serviceId);}
  async function changeServiceProgress(serviceId){const record=selected(),service=findService(serviceId);if(!record||!service)return;pendingConfirmId=null;const at=nowISO(),next=service.status==='not_started'?'in_progress':'completed';transitionService(service,next,at);service.events.unshift({at,title:next==='in_progress'?'Work started':'Service completed',note:next==='in_progress'?'Service work has started.':'Service item marked complete.'});record.updatedAt=at;await saveRecord(record);await reload();renderDetail();toast(`${service.title}: ${itemStatusLabel(service.status)}`);}
  function openStatusModal(serviceId){const service=findService(serviceId);if(!service)return;$('#statusServiceItemId').value=service.id;$('#statusServiceTitle').value=`${service.type} — ${service.title}`;$('#statusSelect').value=service.status;$('#statusNote').value='';$('#detailOverlay').classList.remove('hidden');$('#statusOverlay').classList.remove('hidden');requestAnimationFrame(()=>$('#statusSelect').focus());}
  function openExtraService(){const record=selected();if(!record)return;$('#extraServiceForm').reset();$('#extraServiceVehicle').textContent=`${record.plate}${record.vehicle?` · ${record.vehicle}`:''}`;updateExtraServiceDefaults();$('#extraServiceOverlay').classList.remove('hidden');}
  function updateExtraServiceDefaults(){const type=$('#extraServiceType').value;$('#extraServiceItemTitle').value=defaultTitles[type]||'';$('#extraServiceEstimate').value=estimates[type]||'';}
  async function saveExtraService(event){event.preventDefault();const record=selected();if(!record)return;const type=$('#extraServiceType').value,title=$('#extraServiceItemTitle').value.trim();if(!title)return toast('Add a title for this service item');const at=nowISO(),request=$('#extraServiceRequest').value.trim();record.services.push(makeServiceItem({type,title,estimate:$('#extraServiceEstimate').value.trim()||suggestEstimate(type,request).text,request,at,events:[{at,title:'Service item added',note:request||'New service item added to the existing vehicle record.'}]}));record.updatedAt=at;await saveRecord(record);await reload();closeOverlay('extraServiceOverlay');renderDetail();toast('New service item added to this vehicle record');}
  function openResumeService(){const record=selected();if(!record)return;const options=previousServices(record);$('#resumeServiceVehicle').textContent=`${record.plate} · Choose a previous service to continue.`;$('#resumeServiceOptions').innerHTML=options.length?options.map(({source,service,lastUpdate})=>`<button type="button" class="resume-option" data-source-record="${esc(source.id)}" data-source-service="${esc(service.id)}"><span class="resume-option-main"><b>${esc(service.title)}</b><small><span class="service-tag ${typeClass(service.type)}">${esc(service.type)}</span> · Last updated ${dateLabel(lastUpdate)}</small><small>Previous record · ${dateLabel(source.createdAt)}</small></span><span class="resume-arrow">Continue →</span></button>`).join(''):'<div class="request-box">No previous services are available to continue.</div>';$('#resumeServiceOverlay').classList.remove('hidden');$$('.resume-option', $('#resumeServiceOptions')).forEach(button=>button.addEventListener('click',()=>resumePreviousService(button.dataset.sourceRecord,button.dataset.sourceService)));}
  async function resumePreviousService(sourceRecordId,sourceServiceId){const latest=selected(),source=records.find(record=>record.id===sourceRecordId),oldService=source&&getItems(source).find(service=>service.id===sourceServiceId);if(!latest||!source||!oldService||oldService.migratedTo)return toast('That previous service is no longer available');const at=nowISO(),newService={...oldService,id:makeId(),status:'not_started',migratedTo:null,migratedFrom:{recordId:source.id,serviceId:oldService.id},createdAt:at,updatedAt:at,startedAt:null,completedAt:null,actualDurationMinutes:0,workSessions:[],expectedCompletionAt:new Date(new Date(at).getTime()+(Number(oldService.estimateMinutes)||60)*60000),events:[...(oldService.events||[]).map(event=>({...event})),{at,title:'Service continued in latest vehicle record',note:`Previous service history copied from the ${dateLabel(source.createdAt)} vehicle record.`}]};latest.services.push(newService);latest.updatedAt=at;oldService.migratedTo={recordId:latest.id,serviceId:newService.id};oldService.events.unshift({at,title:'Transferred to latest record',note:`Service continued in the vehicle record created ${dateLabel(latest.createdAt)}.`});source.updatedAt=at;await saveRecord(source);await saveRecord(latest);await reload();closeOverlay('resumeServiceOverlay');openDetail(latest.id);toast('Previous service and its history were added to the latest vehicle record');}
  async function saveStatusChange(event){event.preventDefault();const record=selected(),service=findService($('#statusServiceItemId').value);if(!record||!service)return;const next=$('#statusSelect').value,note=$('#statusNote').value.trim();if(!note)return toast('Add a short note explaining this update');const previous=service.status,at=nowISO();transitionService(service,next,at,note);service.events.unshift({at,title:previous===next?'Service update':`Status changed: ${itemStatusLabel(previous)} → ${itemStatusLabel(next)}`,note});record.updatedAt=at;await saveRecord(record);await reload();closeOverlay('statusOverlay');renderDetail();toast('Status and service history updated');}
  async function addServiceNote(serviceId){const service=findService(serviceId);if(!service)return;const note=window.prompt(`Add an update for “${service.title}”`);if(note===null)return;if(!note.trim())return toast('Add a short note to save this update');service.events.unshift({at:nowISO(),title:'Progress update',note:note.trim()});selected().updatedAt=nowISO();await saveRecord(selected());await reload();renderDetail();toast('Service update saved');}
  function showFullHistory(serviceId){const service=findService(serviceId);if(!service)return;service.showAllEvents=!service.showAllEvents;renderDetail();}
  function closeOverlay(id){$(`#${id}`).classList.add('hidden');if(id==='cameraOverlay')stopCamera();if(id==='detailOverlay')pendingConfirmId=null;}
  function openDetail(id){selectedId=id;renderDetail();}
  function chooseServices(){return $$('.service-checks input:checked').map(input=>input.value);}
  function renderServiceInputs(preserve=true){const prior={};$$('.service-item-input', $('#serviceItemInputs')).forEach(row=>{const type=row.dataset.type,estimate=$('.service-estimate-input',row);prior[type]={title:$('.service-title-input',row).value,estimate:estimate.value,edited:estimate.dataset.userEdited==='true'};});const selected=chooseServices();$('#serviceItemsField').classList.toggle('hidden',selected.length===0);$('#serviceItemInputs').innerHTML=selected.map(type=>{const suggestion=suggestEstimate(type,$('#requestInput').value),values=preserve&&prior[type]?prior[type]:{title:defaultTitles[type],estimate:suggestion.text,edited:false};return `<div class="service-item-input" data-type="${type}"><span class="service-tag ${typeClass(type)}">${type}</span><input class="service-title-input" type="text" aria-label="${type} service item title" value="${esc(values.title)}" placeholder="Service item title" required><input class="service-estimate-input" type="text" aria-label="${type} estimated time" value="${esc(values.estimate)}" data-user-edited="${values.edited?'true':'false'}" placeholder="Est. time"><span class="service-estimate-mark">${suggestion.count?`based on ${suggestion.count} jobs`:'editable'}</span></div>`;}).join('');if(selected.length)applyHistoricalEstimates();}
  function applyHistoricalEstimates(){const description=$('#requestInput').value;let count=0;$$('.service-item-input', $('#serviceItemInputs')).forEach(row=>{const estimate=$('.service-estimate-input',row);if(estimate.dataset.userEdited==='true')return;const recommendation=suggestEstimate(row.dataset.type,description);estimate.value=recommendation.text;if(recommendation.count)count+=recommendation.count;$('.service-estimate-mark',row).textContent=recommendation.count?`based on ${recommendation.count} jobs`:'editable';});if(count)$('#estimateNote').textContent=`Estimate references ${count} completed historical service record${count===1?'':'s'} of the same type. You can edit each estimate.`;else $('#estimateNote').textContent='No completed time records match yet. Using an editable baseline estimate.';}
  function openIntake(){const form=$('#intakeForm');form.reset();delete form.dataset.summaryTitle;currentPhoto='';$$('.service-checks input').forEach(input=>input.checked=false);renderServiceInputs(false);$('#vehicleSuggestions').innerHTML='';$('#vehicleSuggestions').classList.add('hidden');$('#photoPreview').innerHTML='<span class="camera-glyph">▧</span><span>Take a photo or upload an image</span>';$('#scanHint').textContent='A clear registration plate helps OCR.';$('#estimateNote').textContent=AI_ANALYSIS_ENDPOINT?'Connected AI can suggest an estimate for each selected item. Review and edit before saving.':'Editable time suggestions are generated from service type. Connect an AI endpoint for vehicle-specific predictions.';$('#intakeOverlay').classList.remove('hidden');requestAnimationFrame(()=>$('#plateInput').focus());}
  function showVehicleSuggestions(value,showAll=false){const panel=$('#vehicleSuggestions'),query=value.trim().toLowerCase();if(!query&&!showAll){panel.innerHTML='';panel.classList.add('hidden');return;}const unique=new Map();for(const record of [...records].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))){const key=record.plate.trim().toUpperCase(),prior=unique.get(key);if(!prior||(overallStatus(prior)==='completed'&&overallStatus(record)!=='completed'))unique.set(key,record);}const matches=[...unique.values()].filter(record=>!query||[record.plate,record.vehicle,record.customer,record.phone,record.email,record.customerCode].some(field=>(field||'').toLowerCase().includes(query))).slice(0,6);if(!matches.length){panel.innerHTML=`<div class="suggestion-empty">No matching vehicle found</div>`;panel.classList.remove('hidden');positionVehicleSuggestions(panel);return;}panel.innerHTML=`<span class="suggestion-heading">Existing vehicles · one result per plate</span>${matches.map(record=>`<button type="button" class="vehicle-suggestion" data-record-id="${esc(record.id)}" role="option"><span class="suggestion-plate">${esc(record.plate)}</span><span class="suggestion-vehicle">${esc(record.vehicle||'Vehicle details pending')}</span><span class="suggestion-customer">${esc(record.customer||'Customer not listed')}</span><span class="suggestion-state ${overallStatus(record)==='completed'?'':'active'}">${overallStatus(record)==='completed'?'Previous':'Active'}</span></button>`).join('')}`;panel.classList.remove('hidden');positionVehicleSuggestions(panel);}
  function positionVehicleSuggestions(panel){const grid=$('#intakeForm .form-grid'),anchor=document.activeElement?.closest('.field');if(!grid||!anchor)return;const gridRect=grid.getBoundingClientRect(),anchorRect=anchor.getBoundingClientRect();panel.style.top=`${anchorRect.bottom-gridRect.top+5}px`;panel.style.left=`${anchorRect.left-gridRect.left}px`;panel.style.width=`${anchorRect.width}px`;}
  function selectExistingVehicle(recordId){const record=records.find(item=>item.id===recordId);if(!record)return;$('#plateInput').value=record.plate;$('#vehicleInput').value=record.vehicle||'';$('#customerInput').value=record.customer||'';$('#phoneInput').value=record.phone||'';$('#emailInput').value=record.email||'';$('#vehicleSuggestions').classList.add('hidden');$('#vehicleSuggestions').innerHTML='';toast(`Loaded ${record.plate} from existing vehicle records`);}
  async function photoData(file){const bitmap=await createImageBitmap(file);const scale=Math.min(1,1440/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.76));if(!blob)throw new Error('Could not prepare the vehicle photo.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob);});}
  async function loadOcr(){if(window.Tesseract)return window.Tesseract;if(!visionLibraryPromise)visionLibraryPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';script.onload=()=>resolve(window.Tesseract);script.onerror=()=>reject(new Error('Could not load the photo text reader.'));document.head.appendChild(script);});return visionLibraryPromise;}
  async function scanPlateFromPhoto(){if(!currentPhoto)return toast('Take or upload a vehicle photo first');$('#scanPlateBtn').textContent='Reading…';$('#scanHint').textContent='Reading text in photo…';try{const tesseract=await loadOcr();const result=await tesseract.recognize(currentPhoto,'eng');const text=result.data.text.toUpperCase();const candidates=text.match(/\b[A-Z0-9]{5,8}\b/g)||[];const plate=candidates.find(value=>/[A-Z]/.test(value)&&/\d/.test(value));if(plate){$('#plateInput').value=plate;$('#scanHint').textContent=`Plate found: ${plate} · please verify`;toast(`Plate detected: ${plate}`);}else{$('#scanHint').textContent='No clear plate found. Enter it manually or retake the photo.';toast('Could not read a plate. Try a closer photo.');}}catch(error){console.error(error);$('#scanHint').textContent='Photo text reader could not load. Enter the plate manually.';toast(error.message||'Photo reading failed');}finally{$('#scanPlateBtn').textContent='Scan photo';}}
  async function runAiAnalysis(){if(!AI_ANALYSIS_ENDPOINT||(!currentPhoto&&!$('#requestInput').value.trim()))return;const form=new FormData();if(currentPhoto)form.append('photo',await(await fetch(currentPhoto)).blob(),'vehicle.jpg');form.append('serviceItems',JSON.stringify(chooseServices().map(type=>({type,title:$(`.service-item-input[data-type="${type}"] .service-title-input`)?.value||defaultTitles[type],estimate:$(`.service-item-input[data-type="${type}"] .service-estimate-input`)?.value||''}))));form.append('request',$('#requestInput').value.trim());form.append('service',chooseServices().join(','));$('#estimateNote').textContent='AI is analysing the request and service items…';try{const response=await fetch(AI_ANALYSIS_ENDPOINT,{method:'POST',body:form});if(!response.ok)throw new Error(`AI service returned ${response.status}`);const result=await response.json();if(result.plate&&!$('#plateInput').value.trim())$('#plateInput').value=result.plate;if(result.vehicle&&!$('#vehicleInput').value.trim())$('#vehicleInput').value=result.vehicle;if(result.summaryTitle)$('#intakeForm').dataset.summaryTitle=result.summaryTitle;if(Array.isArray(result.services)){for(const item of result.services){const row=$(`.service-item-input[data-type="${CSS.escape(item.type)}"]`);if(row&&item.title)$('.service-title-input',row).value=item.title;if(row&&(item.estimatedTime||item.estimatedMinutes)){const estimate=$('.service-estimate-input',row);if(estimate.dataset.userEdited!=='true'){estimate.value=item.estimatedTime||durationText(item.estimatedMinutes);estimate.dataset.userEdited='false';}}}}else if(result.estimatedTime||result.estimatedMinutes){const first=$('.service-estimate-input');if(first&&first.dataset.userEdited!=='true'){first.value=result.estimatedTime||durationText(result.estimatedMinutes);first.dataset.userEdited='false';}}$('#estimateNote').textContent='AI suggestions are ready. Review and edit service titles and estimates before saving.';}catch(error){console.error(error);$('#estimateNote').textContent='AI analysis was unavailable. Historical time estimates remain available.';}}
  async function acceptPhoto(file){if(!file)return;if(!file.type.startsWith('image/'))return toast('Choose an image file');if(file.size>8*1024*1024)return toast('Photo must be 8 MB or smaller');try{currentPhoto=await photoData(file);$('#photoPreview').innerHTML=`<img src="${currentPhoto}" alt="Vehicle photo preview">`;$('#scanHint').textContent='Photo ready. Scan the registration or let connected AI analyse it.';runAiAnalysis();}catch(error){toast('Could not read this photo');}}
  async function startCamera(){if(!navigator.mediaDevices?.getUserMedia)return toast('Camera access requires HTTPS or localhost in a supported browser.');try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facingMode}},audio:false});$('#cameraVideo').srcObject=cameraStream;$('#cameraOverlay').classList.remove('hidden');}catch(error){console.error(error);toast('Camera access was blocked. Check browser permissions.');}}
